import{_ as t,o as s,c as a,a0 as o}from"./chunks/framework.B9sLprCo.js";const g=JSON.parse('{"title":"DeepSeek Harness 架构","description":"","frontmatter":{"editSource":"docs/architecture.md"},"headers":[],"relativePath":"reference/index.md","filePath":"reference/index.md"}'),d={name:"reference/index.md"};function r(n,e,c,p,i,l){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="deepseek-harness-架构" tabindex="-1">DeepSeek Harness 架构 <a class="header-anchor" href="#deepseek-harness-架构" aria-label="Permalink to &quot;DeepSeek Harness 架构&quot;">​</a></h1><p>改动 <code>packages/</code> 下的任何内容之前，请先阅读本文。本文假定你已了解 Cordis；如果尚未了解，请先阅读<a href="./cordis-primer">入门</a>或<a href="./../develop/cordis-tutorial/">教程</a>。</p><p>建议使用 agent（智能体）探索代码库并理解其架构。</p><h2 id="cordis" tabindex="-1">Cordis <a class="header-anchor" href="#cordis" aria-label="Permalink to &quot;Cordis&quot;">​</a></h2><p><a href="./cordis-primer">Cordis</a> 是 dsh 底层的框架：插件向共享上下文贡献服务、类型化事件和可逆的副作用。产品的每一部分都是插件，包括模型适配器、工具注册表、会话日志，以及 agent loop（智能体循环）本身，因此每一部分都可以从配置替换。</p><p>不存在需要打补丁的特权内核：扩展 dsh 的方式是把插件挂载到其他插件旁边，而各项注册都是副作用，会在其插件卸载时撤销。</p><h2 id="profile-与组合包" tabindex="-1">Profile 与组合包 <a class="header-anchor" href="#profile-与组合包" aria-label="Permalink to &quot;Profile 与组合包&quot;">​</a></h2><p>运行中的 <code>dsh</code> 是一棵插件树，由启动时按序叠加的各层组合而成。</p><p><strong>profile</strong> 是存放在 Harness home 中的具名组装。它列出自己叠放的组合包，存放自己安装的树外插件，并保存用户自己的 <code>cordis.patch.yml</code>。<code>web</code> 和 <code>headless</code> 作为模板随发行版交付。</p><p><strong>组合包</strong>是 Cordis 配置项及其挂载代码的分发格式，因此它插入的内容始终可被其上各层 patch。</p><p>两者都在各自的 <code>package.json</code> 中通过 <code>dsh</code> 字段声明自己：<code>dsh.profile</code> 列出一个 profile 的组合包，<code>dsh.bundle</code> 指向一个组合包的 patch 文件。</p><p><a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/bundle/base/README.md" target="_blank" rel="noreferrer"><code>dsh-base</code></a> 是每个 profile 的第一层：模型适配器、工具、持久化、沙箱与审批策略、设置、凭据、遥测。<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/bundle/web-app/README.md" target="_blank" rel="noreferrer"><code>dsh-web-app</code></a> 增加浏览器应用；<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/bundle/headless/README.md" target="_blank" rel="noreferrer"><code>dsh-headless</code></a> 增加一次性运行器，且完全不带服务器。</p><p>各层按此顺序应用在空条目列表之上：先按 profile 列出的顺序应用每个组合包，然后是 profile 的 <code>cordis.patch.yml</code>，然后是 home 级的那份，最后是任意 <code>--patch</code> overlay。一条 patch 按 id 定位某个条目并替换其整个 config，或插入新条目。</p><p>要查看你的机器实际启动的配置树：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dump-config</span></span></code></pre></div><p>它打印出的任何条目，都可以由你自己的 patch 替换。</p><p>组装机制见 <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/boot/app-boot/README.md#profiles" target="_blank" rel="noreferrer">app-boot</a>；配置字段见生成的<a href="./config-catalog">配置目录</a>。</p><h2 id="核心包" tabindex="-1">核心包 <a class="header-anchor" href="#核心包" aria-label="Permalink to &quot;核心包&quot;">​</a></h2><p>以下是向 Cordis 树贡献内容的部分核心包。</p><table tabindex="0"><thead><tr><th>包</th><th>职责</th><th><code>ctx</code> 键</th></tr></thead><tbody><tr><td><a href="./subsystems/session"><code>core/session</code></a></td><td>仅追加的 <code>SessionEvent</code> 日志和内存存储</td><td><code>ctx.sessions</code></td></tr><tr><td><a href="./subsystems/system-prompt"><code>core/system-prompt</code></a></td><td>提示词片段与工具 schema 的组装</td><td><code>ctx.systemPrompt</code></td></tr><tr><td><a href="./subsystems/tools"><code>core/tools</code></a></td><td>作用域化的工具注册表和带把关的执行流水线</td><td><code>ctx.tools</code></td></tr><tr><td><a href="./subsystems/core"><code>core/agent</code></a></td><td><code>Agent</code> 接口、活跃 agent 注册表和 <code>agent/*</code> 事件</td><td><code>ctx.agents</code></td></tr><tr><td><a href="./subsystems/core"><code>core/agent-loop</code></a></td><td>实现该接口的默认驱动器</td><td><code>ctx.agentLoop</code></td></tr><tr><td><a href="./subsystems/scope"><code>core/scope</code></a></td><td>按 agent 划分作用域的注册原语</td><td>库，无 ctx 键</td></tr><tr><td><a href="./subsystems/llm-streaming"><code>llm/llm</code></a></td><td>消息与流式词汇表，以及适配器 seam</td><td><code>ctx.llm</code></td></tr></tbody></table><p><a id="events"></a></p><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>事件就是扩展点，而选对事件域是大多数改动的第一个决定。</p><ul><li><strong>会话事件</strong>是追加到日志并通过 <code>session/event</code> 广播的持久事实。当某个事实必须在重新加载后仍然存在时，使用它。</li><li><strong>Agent 事件</strong>（<code>agent/*</code>）携带活跃 <code>Agent</code>：inbox、步骤、状态、请求、验证、续跑。要观察或拦截进行中的工作时，使用它。</li><li><strong>能力事件</strong>无需导入循环即可向某个 seam（<code>fs/*</code>、<code>tools/*</code>、<code>telemetry/*</code>）附加策略和适配器。</li></ul><p><a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/docs/event-producer-consumer.md" target="_blank" rel="noreferrer">事件映射</a>列出每个事件的生产方与消费方。</p><p><a id="turn-flow"></a></p><h2 id="轮次流程" tabindex="-1">轮次流程 <a class="header-anchor" href="#轮次流程" aria-label="Permalink to &quot;轮次流程&quot;">​</a></h2><p>一个<strong>步骤</strong>是一次模型请求加上它调用的工具。一个<strong>轮次</strong>包含零个或多个步骤：它在领取首条输入之前打开，并在不再欠下任何工作时关闭。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>turn/start</span></span>
<span class="line"><span>  claim next-step input plus one queued message</span></span>
<span class="line"><span>  assemble prompt sections + tool schemas</span></span>
<span class="line"><span>  -&gt; agent/pre-step                   reject | enter(messages)</span></span>
<span class="line"><span>     reject, or a first enter rewritten empty -&gt; close the turn with no step</span></span>
<span class="line"><span>     step/start</span></span>
<span class="line"><span>     append entered messages as user/message</span></span>
<span class="line"><span>     derive model history from the log</span></span>
<span class="line"><span>     agent/request -&gt; llm/stream -&gt; assistant/chunk* -&gt; assistant/message</span></span>
<span class="line"><span>     tool/call* -&gt; tools/pre-execute -&gt; tools/execute -&gt; tools/post-execute -&gt; tool/result*</span></span>
<span class="line"><span>     step/end</span></span>
<span class="line"><span>     tools owe another request, or next-step input arrived -&gt; claim -&gt; next step</span></span>
<span class="line"><span>  -&gt; agent/turn-stopping</span></span>
<span class="line"><span>turn/end</span></span></code></pre></div><p><code>turn/*</code>、<code>step/*</code>、<code>user/message</code>、<code>assistant/*</code> 和 <code>tool/*</code> 是持久会话事件；其余是分属三个事件域的实时扩展点。<code>agent/pre-step</code>、<code>agent/request</code>、<code>llm/stream</code> 和三个 <code>tools/*</code> 事件是 waterfall（瀑布式事件），其监听器必须调用 <code>next()</code> 才能委托下去；<code>agent/turn-stopping</code> 是 serial 事件，没有 <code>next()</code>。</p><p>输入通过同一个 inbox 到达驱动器。有些消息会立即唤醒它；注入的上下文会留在 inbox 中，直到另一条消息将其唤醒。</p><p><code>agent/pre-step</code> 决定模型看到什么。监听器可以改写已领取的消息，也可以直接拒绝它们；首次领取被拒绝或被改写为空时，仍会关闭一个不含步骤的持久轮次，因此日志会记录这次尝试。每个步骤读取插件注册的提示词片段和工具 schema。</p><p>详情见<a href="./agent-lifecycle">时序图</a>、<a href="./tool-execution-pipeline">工具流水线</a>和<a href="./subsystems/core#the-agent-handle">取消与错误恢复</a>。</p><h2 id="会话日志" tabindex="-1">会话日志 <a class="header-anchor" href="#会话日志" aria-label="Permalink to &quot;会话日志&quot;">​</a></h2><p>会话日志是模型所见上下文的来源。<code>deriveMessages()</code> 从中投影出模型历史，原始 <code>assistant/chunk</code> 事件则保证回放和 UI 保真。fork、恢复、transcript（文本记录）、遥测和持久化都派生自该事件流。</p><p><strong>模型可见即已记录。</strong> 抵达模型请求的一切都必须能从日志重建，并由一项运行时不变量断言这一点。因此，新增一项模型可见输入就需要新增一个会话事件：扩展 <code>SessionEventMap</code> 并从日志渲染。</p><h2 id="能力-seam" tabindex="-1">能力 seam <a class="header-anchor" href="#能力-seam" aria-label="Permalink to &quot;能力 seam&quot;">​</a></h2><p>一个 <strong>seam</strong> 是一项可替换能力，包含三种角色：声明接口的 <strong>Service Definition</strong>、实现它的 <strong>Service Provider</strong>，以及使用它的 <strong>Consumer</strong>（通常是面向模型的工具）。一个包可以合并承担多个角色，但单一角色本身不是 seam；添加一项能力意味着把三者一并设计（<a href="./capability-seams">能力图</a>）。</p><p>seam 正是替换一个提供方就能改变整个产品的原因。文件系统与进程提供方共享同一个执行世界，因此把二者指向同一远程执行环境，就会把 Bash、PTY 和 LSP 一并搬过去，无需提供方专用 fork。Remote-SSH marker 就是这种执行环境，而不是沙箱；沙箱策略仍由独立提供方负责。桌面端的 marker 实现会把这些能力发送给 Go agent，同时让 Host 控制平面留在本地（决策）。<a href="./subsystems/subagent">subagent 提供方</a>在同一个接口之后同样千差万别，从新建一个子 agent，到把一个轮次委派给另一个产品。</p><p><a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/docs/subsystems/agent-team.md" target="_blank" rel="noreferrer">实验性 Agent Teams</a> 是 <code>ctx.agentTeams</code> 上的私有显式启用协作 seam，在可继续 subagent 之上提供持久 roster、任务板和 mailbox。</p><h2 id="新行为的归属位置" tabindex="-1">新行为的归属位置 <a class="header-anchor" href="#新行为的归属位置" aria-label="Permalink to &quot;新行为的归属位置&quot;">​</a></h2><p>新行为附加到已有文档记录的扩展点。改动循环本身时，本映射随之更新。</p><table tabindex="0"><thead><tr><th>目标</th><th>机制</th></tr></thead><tbody><tr><td>添加模型提供方</td><td>在 <code>ctx.llm</code> 上注册其适配器</td></tr><tr><td>添加面向模型的能力</td><td>在 <code>ctx.tools</code> 上注册；其 schema 加入提示词组装</td></tr><tr><td>让某个会话拥有不同的能力集合</td><td>组装一个 agent preset；其中的服务行需要 <code>isolate</code> realm</td></tr><tr><td>添加 shell 执行</td><td>注册 <code>ctx.shell</code> 后端；本地后端通过 <code>ctx.subprocess</code> spawn 进程</td></tr><tr><td>添加持久化终端执行</td><td>注册 <code>ctx.terminals</code> 后端和 <code>dsh-tool-terminal</code></td></tr><tr><td>添加用户命令</td><td>在 <code>ctx.commands</code> 上注册；它无需模型轮次即可分派</td></tr><tr><td>添加后台工作</td><td>在 <code>ctx.jobs</code> 上注册；<code>job_*</code> 工具负责收集或停止</td></tr><tr><td>添加文件系统访问或策略</td><td>注册 <code>ctx.fs</code> 提供方，或监听 <code>fs/*</code> 事件</td></tr><tr><td>限制所启动的进程</td><td>使用 <code>ctx.sandbox</code> 后端；消费方在启动进程前包装 argv</td></tr><tr><td>拦截请求、工具或轮次</td><td>使用相应的 <code>agent/*</code> 或 <code>tools/*</code> 事件；<code>agent/turn-stopping</code> 会停止轮次</td></tr><tr><td>添加模型可见上下文</td><td>调用 <code>agent.inject()</code>；它会落到下一次获准的请求中</td></tr><tr><td>添加 UI 或编辑器集成</td><td>驱动 <code>ctx.agents</code> 并从 <code>session/event</code> 渲染</td></tr><tr><td>添加 Web Client Chat 节点</td><td>注册 <code>ConversationNodeDefinition</code> + keyed renderer</td></tr><tr><td>添加持久会话状态</td><td>扩展 <code>SessionEventMap</code>；从日志渲染和回放</td></tr><tr><td>生成会话标题</td><td>注册唯一的 <code>ctx.sessionTitle</code> 提供方</td></tr><tr><td>管理同会话目标</td><td>使用 <code>ctx.goals</code>；通过 <code>agent/*</code> 续跑</td></tr><tr><td>fork 活跃会话</td><td><code>ctx.sessions.fork(source, boundary?, childSessionId?)</code></td></tr><tr><td>将注册项限定到单个 agent</td><td>使用该 agent 的 <code>agent.ctx</code></td></tr></tbody></table><p><a href="./cookbook/extension-cookbook">扩展实操手册</a>将功能映射到能力，并索引<a href="./cookbook/adding-a-package">包</a>、<a href="./cookbook/adding-a-tool">工具</a>、<a href="./cookbook/adding-an-llm-adapter">LLM（大语言模型）适配器</a>、<a href="./cookbook/adding-a-conversation-node">Chat 节点</a>和<a href="./cookbook/adding-a-settings-card">设置卡片</a>的分步指南。</p>`,44)])])}const m=t(d,[["render",r]]);export{g as __pageData,m as default};
